// src/app/api/v1/stream/route.ts  (tested shape: Response(ReadableStream), request.signal abort cleanup, 1 s cadence, no buffering on Next 16.4.3 standalone)
import { bus } from '@/lib/bus' // globalThis-backed, NOT module-level state
export const dynamic = 'force-dynamic'
export const runtime = 'nodejs'
const enc = new TextEncoder()
export async function GET(request: Request) {
  const lastId = request.headers.get('last-event-id') ?? new URL(request.url).searchParams.get('since')
  let off = () => {}
  let ka: ReturnType<typeof setInterval> | undefined
  const stop = () => { off(); if (ka) clearInterval(ka) }
  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      const send = (s: string) => { try { c.enqueue(enc.encode(s)) } catch { stop() } }
      send('retry: 5000\n: connected\n\n')              // headers + first bytes immediately
      for (const r of bus.since(lastId)) send(`id: ${r.ts}\nevent: reading\ndata: ${JSON.stringify(r)}\n\n`)
      off = bus.subscribe((r) => send(`id: ${r.ts}\nevent: reading\ndata: ${JSON.stringify(r)}\n\n`))
      ka = setInterval(() => send(': ka\n\n'), 15_000)
      request.signal.addEventListener('abort', () => { stop(); try { c.close() } catch {} }, { once: true })
    },
    cancel: stop,
  })
  return new Response(stream, { headers: {
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-cache, no-transform',
    'X-Accel-Buffering': 'no',
  } })
}

// src/lib/bus.ts and instrumentation.ts  (module state is NOT shared between register() and routes; globalThis is)
const K = Symbol.for('specs.bus')
type Reading = { ts: number; [k: string]: unknown }
type Bus = { subs: Set<(r: Reading) => void>; ring: Reading[] }
const g = globalThis as unknown as Record<symbol, Bus>
const b: Bus = (g[K] ??= { subs: new Set(), ring: [] })
export const bus = {
  publish(r: Reading) { b.ring.push(r); if (b.ring.length > 120) b.ring.shift(); b.subs.forEach((f) => f(r)) },
  subscribe(f: (r: Reading) => void) { b.subs.add(f); return () => { b.subs.delete(f) } },
  since(id: string | null) { const t = Number(id); return Number.isFinite(t) && id ? b.ring.filter((r) => r.ts > t) : [] },
}
// instrumentation.ts (project root or src/)
export async function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') (await import('./lib/sampler')).start() // start() calls bus.publish every ~5 s
}

