# deploy/specs.caddy: only the (specs) snippet body changes. Works on 2.10.x-2.11.7. No flush_interval (SSE is flushed immediately; -1 would stop upstream cancel on disconnect).
(specs) {
	request_body {
		max_size 64KB
	}
	header {
		Strict-Transport-Security "max-age=31536000"
		X-Content-Type-Options "nosniff"
		Referrer-Policy "strict-origin-when-cross-origin"
		X-Frame-Options "DENY"
		Permissions-Policy "camera=(), microphone=(), geolocation=(), browsing-topics=()"
		X-Robots-Tag "noindex, nofollow, noarchive"
		-Server
	}

	@sse path /api/v1/stream
	handle @sse {
		reverse_proxy specs:3000
	}
	handle {
		encode zstd gzip
		reverse_proxy specs:3000
	}
}
# Alternative without handle: encode { match { header Content-Type text/html* ; header Content-Type text/css* ; header Content-Type text/plain* ; header Content-Type application/json* ; header Content-Type application/javascript* ; header Content-Type image/svg+xml* } }  (explicit allowlist; no negation exists)

// SseProvider.tsx ('use client'): mount once in the root layout. Handles CLOSED (browser gave up on non-200, e.g. Caddy 502 during deploy).
useEffect(() => {
  let es: EventSource | null = null, timer: ReturnType<typeof setTimeout> | undefined, attempt = 0, lastId = '', hiddenTimer: ReturnType<typeof setTimeout> | undefined
  const open = () => {
    es = new EventSource('/api/v1/stream' + (lastId ? `?since=${lastId}` : ''))
    es.addEventListener('reading', (e) => { lastId = (e as MessageEvent).lastEventId; attempt = 0; onReading(JSON.parse((e as MessageEvent).data)) })
    es.onerror = () => {
      if (es && es.readyState === EventSource.CLOSED) {      // CONNECTING means the browser is retrying itself
        es.close(); es = null
        timer = setTimeout(open, Math.min(30_000, 1000 * 2 ** attempt++) + Math.random() * 500)
      }
    }
  }
  const onVis = () => {
    if (document.visibilityState === 'hidden') hiddenTimer = setTimeout(() => { es?.close(); es = null }, 45_000)
    else { clearTimeout(hiddenTimer); if (!es) { clearTimeout(timer); open() } }
  }
  open(); document.addEventListener('visibilitychange', onVis)
  return () => { document.removeEventListener('visibilitychange', onVis); clearTimeout(timer); clearTimeout(hiddenTimer); es?.close() }
}, [])

