/* globals.css: view transitions + reduced motion + details */
::view-transition { pointer-events: none; }
::view-transition-group(site-header) { animation: none; z-index: 100; }
::view-transition-old(site-header) { display: none; }
::view-transition-new(site-header) { animation: none; }
::view-transition-old(.nav-forward) { --o: -48px; animation: 150ms ease-in both fade reverse, 350ms ease-in-out both slide reverse; }
::view-transition-new(.nav-forward) { --o: 48px;  animation: 210ms ease-out 150ms both fade, 350ms ease-in-out both slide; }
::view-transition-old(.nav-back)    { --o: 48px;  animation: 150ms ease-in both fade reverse, 350ms ease-in-out both slide reverse; }
::view-transition-new(.nav-back)    { --o: -48px; animation: 210ms ease-out 150ms both fade, 350ms ease-in-out both slide; }
@keyframes fade  { from { opacity: 0 } to { opacity: 1 } }
@keyframes slide { from { translate: var(--o) } to { translate: 0 } }
@media (prefers-reduced-motion: reduce) {
  ::view-transition-old(*), ::view-transition-new(*), ::view-transition-group(*) { animation-duration: 0s !important; animation-delay: 0s !important; }
}
/* <details>: animate only where interpolate-size exists (Chrome/Edge 129+); elsewhere open/close is instant */
details::details-content { block-size: 0; overflow: clip; }
details[open]::details-content { block-size: auto; }
@supports (interpolate-size: allow-keywords) {
  :root { interpolate-size: allow-keywords; }
  details::details-content { transition: block-size .25s ease, content-visibility .25s allow-discrete; }
}
@media (prefers-reduced-motion: reduce) { details::details-content { transition: none; } }
